<?php $this->insert('_order_products', ['items' => $order['items'], 'unit_prices' => true, 'product_view_url' => $product_view_url ?? '']) ?>
<section class="yc-panel"><h2>배송 정보</h2><dl class="yc-detail-list"><div><dt>받는 분</dt><dd><?= $this->e($order['recipient']) ?> · <?= $this->e(\GnuCms\Aligo\PhoneNumber::format((string) $order['recipient_phone'])) ?></dd></div><div><dt>주소</dt><dd>(<?= $this->e($order['postcode']) ?>) <?= $this->e($order['address'] . ' ' . $order['address_detail']) ?></dd></div><?php if ($order['delivery_note'] !== ''): ?><div><dt>배송 요청</dt><dd><?= $this->e($order['delivery_note']) ?></dd></div><?php endif ?>
  <?php if ($order['carrier'] !== ''): $trackingLabel = $order['carrier'] . ($order['tracking_number'] !== '' ? ' · ' . $order['tracking_number'] : ''); $trackingUrl = \GnuCms\Shop\Settings::trackingUrl((string) $order['carrier'], (string) $order['tracking_number']); ?><div><dt>운송장</dt><dd><?php if ($trackingUrl !== null): ?><a class="yc-tracking-link" href="<?= $this->e($trackingUrl) ?>" target="_blank" rel="noopener noreferrer" aria-label="<?= $this->e($trackingLabel . ' 배송조회, 새 창') ?>"><?= $this->e($trackingLabel) ?> <span aria-hidden="true">↗</span></a><?php else: ?><?= $this->e($trackingLabel) ?><?php endif ?></dd></div><?php endif ?>
</dl>
<?php if ($order['shipping'] !== []): ?><details class="yc-shipping-details"><summary>상품별 배송비 확인</summary><ul><?php foreach ($order['shipping'] as $delivery): ?><li><?= $this->e($delivery['name']) ?> · <?= $delivery['mode'] === 'cod' ? '착불' : '선불' ?> <?= number_format((int) $delivery['fee']) ?>원<?= $delivery['shared'] ? ' (기본배송 묶음)' : '' ?></li><?php endforeach ?></ul></details><?php endif ?>
</section>
<section class="yc-panel"><h2>주문자 정보</h2><dl class="yc-detail-list"><div><dt>주문자</dt><dd><?= $this->e($order['buyer_name']) ?></dd></div><div><dt>연락처</dt><dd><?= $this->e(\GnuCms\Aligo\PhoneNumber::format((string) $order['phone'])) ?></dd></div><?php if ($order['email'] !== ''): ?><div><dt>이메일</dt><dd><?= $this->e($order['email']) ?></dd></div><?php endif ?></dl></section>
